grammar audit.Literal hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !'a';

grammar audit.Range hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !('a'..'z');

grammar audit.Alternatives hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !('a'|'x'|'z');

grammar audit.NestedGroups hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !(('a'..'c')|('x'|'z'));

grammar audit.Fragment hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !LETTER;
terminal fragment LETTER: 'a'..'z';

grammar audit.FragmentAlternatives hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !(LETTER|'0');
terminal fragment LETTER: 'a'..'z';

grammar audit.FragmentNested hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !OUTER;
terminal fragment OUTER: INNER|'x';
terminal fragment INNER: 'a';

grammar audit.Nullable hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !('a'?);

grammar audit.Multichar hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !'ab';

grammar audit.Sequence hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !('a' 'b');

grammar audit.Eof hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !EOF;

grammar audit.Wildcard hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !.;

grammar audit.CyclicFragment hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !A;
terminal fragment A: B;
terminal fragment B: A;

grammar audit.UnknownFragment hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !MISSING;

grammar audit.AstralLiteral hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !'🌍';

grammar audit.AstralRange hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !('🌍'..'🌎');

grammar audit.CommittedFailure hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: 'a' !'b';
terminal SHORT: 'a';

grammar audit.NegatedRepeat hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: (!('a'..'z'))+;

grammar audit.NegationBaseOverride
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
terminal fragment LETTER: 'a';

grammar audit.NegationChildOverride with audit.NegationBaseOverride hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !LETTER;
terminal fragment LETTER: 'b';

grammar audit.NegationBaseExplicit
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
terminal fragment LETTER: 'a';

grammar audit.NegationChildExplicit with audit.NegationBaseExplicit hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: !super::LETTER;
terminal fragment LETTER: 'b';

grammar audit.NegationProgramBase
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
terminal VALUE returns ecore::EString: !LETTER;
terminal fragment LETTER: 'a';

grammar audit.NegationProgramChild with audit.NegationProgramBase hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
Model returns k::Model: name=VALUE;
terminal fragment LETTER: 'b';

grammar audit.CommittedPath hidden()
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: name=VALUE;
terminal VALUE returns ecore::EString: 'a' !'b' 'c';
terminal SHORT: 'a';
terminal REST: .;
